*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF40300.xml";
scwin.list_dtl_noti_id;
scwin.vSecugrpID = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_depouser_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=LITMGT_LIST_USR_INFO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.consultmgt.select.depo.user.condition";
    dts_DepoUser.DataID = encodeURI(url);
    dts_DepoUser.reset();
    txb_depo_user.setValue(dts_DepoUser.getCellData(1, "USER_INFO"));
};
scwin.fn_list_sync = function() {
    var isur_cd = txb_com_cd.getValue();
    var emp_nm = txb_user_nm.getValue();
    var startDate = edt_SDate.getValue();
    var endDate = edt_EDate.getValue();
    var searchGubun = mxr_date_gubun.getValue();
    var market_gubun = js_market;
    if (market_gubun == "9") {
        market_gubun = mxr_market_gubun.getValue();
        if (market_gubun == "A") {
            market_gubun = "";
        }
    }
    var url = "/ConsultationBookManagement.do?method=listConsultationBook&inputMessageId=LITMGT_LIST_INOUT&LITMGT_LIST_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&isur_cd=" + isur_cd;
    url += "&emp_nm=" + emp_nm;
    url += "&startDate=" + startDate;
    url += "&endDate=" + endDate;
    url += "&searchGubun=" + searchGubun;
    url += "&market_gubun=" + market_gubun;
    dts_consultationBookList.DataID = encodeURI(url);
    dts_consultationBookList.reset();
    $c.cm.ShowWin(grd_dataList);
};
scwin.fn_setId = function(obj) {
    scwin.list_dtl_noti_id = dts_consultationBookList.getCellData(eval(obj), "LIST_DTL_NOTI_ID");
};
scwin.fn_getId = function() {
    return scwin.list_dtl_noti_id;
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_com_cd.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_com_nm.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_com_cd.setValue(arrPar[0].ISUR_CD);
    txb_com_nm.setValue(arrPar[0].COM_NM);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_com_cd_onkeyup = function() {
    if (txb_com_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_com_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_com_cd_onblur = function() {
    if (txb_com_cd.getValue() == "") {
        txb_com_nm.setValue("");
    }
};
scwin.txb_com_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_com_cd.getValue() == "") {
        txb_com_nm.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_search_onclick = function() {
    $c.lc.fn_PopFindCorpChrg(scwin.vSecugrpID);
};
scwin.dts_DepoUser_OnLoadError = function() {
    $c.stf.alert_error(dts_DepoUser);
};
scwin.dts_consultationBookList_OnLoadError = function() {
    $c.stf.alert_error(dts_consultationBookList);
};
scwin.dts_consultationBookList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_consultationBookList.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_dataList); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_select_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_toexcel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_dataList, "상장알림통보내역", "", "8");
};
scwin.btn_close_onclick = function() {
    self.close();
};
scwin.btn_input_onclick = async function() {
    scwin.list_dtl_noti_id = "input";
    await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF40301.gfm", "상장알림 등록", 200, 100, 690, 350, "window");
    scwin.list_dtl_noti_id = "";
    scwin.fn_list_sync();
};
scwin.grd_dataList_OnDblClick = async function(row, colid) {
    scwin.fn_setId(row);
    await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF40301.gfm", "상장알림 수정", 200, 100, 690, 350, "window");
    scwin.fn_list_sync();
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun, false);
        $c.cm.setColumnProp(grd_dataList, "SPOT_ISU_TRD_MKT_TP_CD", "Show", false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 1));
    edt_EDate.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_com_cd, txb_com_nm);
    scwin.fn_depouser_read_sync();
};
